--
-- TOC entry 245 (class 1255 OID 116433)
-- Name: atualizar_produto(character varying, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.atualizar_produto(p_num_serie character varying, p_name character varying, p_area character varying, p_input_date character varying, p_foto_base64 character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    p_foto_bytea BYTEA;
BEGIN
    -- Converte base64 para BYTEA
    IF p_foto_base64 IS NOT NULL THEN
        p_foto_bytea := decode(p_foto_base64::text, 'base64');
    END IF;

    -- Atualiza os campos
    UPDATE public.produtos
    SET 
        name = COALESCE(p_name, name),
        area = COALESCE(p_area, area),
        input_date = COALESCE(p_input_date, input_date),
        foto = COALESCE(p_foto_bytea, foto)
    WHERE num_serie = p_num_serie;
END;
$$;


ALTER FUNCTION public.atualizar_produto(p_num_serie character varying, p_name character varying, p_area character varying, p_input_date character varying, p_foto_base64 character varying) OWNER TO postgres;

--
