--

CREATE FUNCTION public.buscar_produto(p_num_serie character varying) RETURNS TABLE(id integer, num_serie character varying, name character varying, area character varying, input_date character varying, foto bytea)
    LANGUAGE plpgsql
    AS $$
begin
    return query
    select 
        p.id, 
        p.num_serie, 
        p.name, 
        p.area, 
        p.input_date,
        p.foto
    from produtos p
    where p.num_serie ilike p_num_serie;
end;
$$;


