--
-- TOC entry 234 (class 1255 OID 100054)
-- Name: filtrar_produto(character varying, character varying, character varying, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.filtrar_produto(p_num_serie character varying DEFAULT NULL::character varying, p_name character varying DEFAULT NULL::character varying, p_area character varying DEFAULT NULL::character varying, p_input_date date DEFAULT NULL::date) RETURNS TABLE(id integer, num_serie character varying, name character varying, area character varying, input_date date)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT *
    FROM produtos
    WHERE (p_num_serie IS NULL OR produtos.num_serie ILIKE p_num_serie)
      AND (p_name IS NULL OR produtos.name ILIKE p_name)
      AND (p_area IS NULL OR produtos.area ILIKE p_area)
      AND (p_input_date IS NULL OR produtos.input_date = p_input_date);
END;
$$;


