-- Name: remover_produto(character varying); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.remover_produto(IN p_num_serie character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO historico_produtos_removidos (num_serie, name, area, input_date, foto)
    SELECT num_serie, name, area, input_date, foto
    FROM produtos
    WHERE num_serie = p_num_serie;

    DELETE FROM produtos
    WHERE num_serie = p_num_serie;
END;
$$;


