    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Verifica se há registros na tabela 'usuarios'
    IF EXISTS (SELECT 1 FROM cadastro.usuarios) THEN
        -- Retorna todos os registros da tabela 'usuarios'
        RETURN QUERY 
        SELECT u.id, u.nome_completo, u.endereco, u.idade, u.cpf
        FROM cadastro.usuarios u;
    ELSE
        -- Retorna uma tabela vazia se não houver registros
        RETURN;
    END IF;
END;
$$;


